Lemma strlen_run6 : forall (fx : FPState) regs m (p wv c0 c1 c2 c3 c4 c5 : Z) (ret : word),
  (4096 <= p)%Z -> (p + 8 < 2 ^ 47)%Z -> (p mod 16 = 0)%Z -> (0 <= wv < 2 ^ 64)%Z ->
  (1 <= c0 <= 255)%Z -> (1 <= c1 <= 255)%Z -> (1 <= c2 <= 255)%Z -> (1 <= c3 <= 255)%Z -> (1 <= c4 <= 255)%Z -> (1 <= c5 <= 255)%Z ->
  rdn SEGS m (Z_to_bv 64 (p + 0)) 8 = Some (Z_to_le_bytes 8 wv) ->
  rdn SEGS m (Z_to_bv 64 (p + 0)) 1 = Some (Z_to_le_bytes 1 c0) ->
  rdn SEGS m (Z_to_bv 64 (p + 1)) 1 = Some (Z_to_le_bytes 1 c1) ->
  rdn SEGS m (Z_to_bv 64 (p + 2)) 1 = Some (Z_to_le_bytes 1 c2) ->
  rdn SEGS m (Z_to_bv 64 (p + 3)) 1 = Some (Z_to_le_bytes 1 c3) ->
  rdn SEGS m (Z_to_bv 64 (p + 4)) 1 = Some (Z_to_le_bytes 1 c4) ->
  rdn SEGS m (Z_to_bv 64 (p + 5)) 1 = Some (Z_to_le_bytes 1 c5) ->
  rdn SEGS m (Z_to_bv 64 (p + 6)) 1 = Some (Z_to_le_bytes 1 0) ->
  (forall i, (65536 <= i < 1110016)%Z -> m (Z_to_bv 64 i) = None) ->
  Tc wv <> HZ.HIGHS ->
  getr regs 10 = Z_to_bv 64 p -> getr regs 1 = ret -> ret_ok ret ->
  exists regs', msteps SEGS (@mkst fx regs (Z_to_bv 64 STRLEN_PC) m rom) (@mkst fx regs' ret m rom)
    /\ getr regs' 10 = Z_to_bv 64 6 /\ regs_agree (fun r => In r sl_clob) regs regs'.
Proof.
